CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payer_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, organization_id uuid REFERENCES organizations(id) ON DELETE RESTRICT, tournament_id uuid REFERENCES tournaments(id) ON DELETE RESTRICT, entry_id uuid REFERENCES tournament_entries(id) ON DELETE RESTRICT, payment_type varchar(40) NOT NULL CHECK(payment_type IN ('INDIVIDUAL_REGISTRATION_FEE','TEAM_REGISTRATION_FEE','PLAYER_LICENSE_FEE','OTHER')), amount numeric(12,2) NOT NULL CHECK(amount>=0), currency char(3) NOT NULL DEFAULT 'EUR', status varchar(30) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PROCESSING','PAID','FAILED','CANCELLED','REFUNDED','PARTIALLY_REFUNDED')), provider varchar(50), provider_payment_id varchar(255), provider_customer_id varchar(255), idempotency_key varchar(120) NOT NULL UNIQUE, paid_at timestamptz, failed_at timestamptz, refunded_amount numeric(12,2) NOT NULL DEFAULT 0 CHECK(refunded_amount BETWEEN 0 AND amount), metadata jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_payment_id));

CREATE TABLE user_licenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, sport_id uuid REFERENCES sports(id) ON DELETE RESTRICT, season_id uuid REFERENCES seasons(id) ON DELETE RESTRICT, payment_id uuid REFERENCES payments(id) ON DELETE SET NULL, valid_from timestamptz NOT NULL, valid_until timestamptz NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK(valid_until>valid_from));
